 'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,x.privilege_type,x.is_grantable) order by case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end collate "C",x.privilege_type),'[]') from aclexplode(a.attacl) x)) order by a.attnum),'[]') from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'access',(select jsonb_object_agg(r.name,(select coalesce(jsonb_agg(priv order by priv),'[]') from unnest(array['DELETE','INSERT','REFERENCES','SELECT','TRIGGER','TRUNCATE','UPDATE']) priv where has_table_privilege(r.name,c.oid,priv))) from roles r),
 'publicAccess',exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x where x.grantee=0),'viewHash',case when c.relkind='v' then md5(pg_get_viewdef(c.oid,false)) end) value
 from pg_class c join ns n on n.oid=c.relnamespace where c.relkind in('r','v','p')),
functions as(select format('%I.%I(%s)',n.nspname,p.proname,oidvectortypes(p.proargtypes)) key,jsonb_build_object('owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'language',l.lanname,'volatility',p.provolatile,'strict',p.proisstrict,'leakproof',p.proleakproof,'parallel',p.proparallel,'returnsSet',p.proretset,'result',pg_get_function_result(p.oid),'names',coalesce(to_jsonb(p.proargnames),'[]'),'config',coalesce(to_jsonb(p.proconfig),'[]'),'defaultsHash',md5(pg_get_expr(p.proargdefaults,0)),
 'sourceHash',md5(regexp_replace(p.prosrc,chr(13)||chr(10)||'?',chr(10),'g')),'execute',(select jsonb_object_agg(r.name,has_function_privilege(r.name,p.oid,'execute')) from roles r),'publicExecute',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x where x.grantee=0 and x.privilege_type='EXECUTE')) value from pg_proc p join ns n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where p.prokind='f'),
policies as(select n.nspname||'.'||c.relname||'.'||p.polname key,jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r) from unnest(p.polroles) r),'usingHash',md5(pg_get_expr(p.polqual,p.polrelid)),'checkHash',md5(pg_get_expr(p.polwithcheck,p.polrelid))) value from pg_policy p join pg_class c on c.oid=p.polrelid join ns n on n.oid=c.relnamespace),
triggers as(select n.nspname||'.'||c.relname||'.'||t.tgname key,jsonb_build_object('enabled',t.tgenabled,'hash',md5(pg_get_triggerdef(t.oid))) value from pg_trigger t join pg_class c on c.oid=t.tgrelid join ns n on n.oid=c.relnamespace where not t.tgisinternal),
constraints as(select n.nspname||'.'||c.relname||'.'||x.conname key,jsonb_build_object('kind',x.contype,'validated',x.convalidated,'hash',md5(pg_get_constraintdef(x.oid))) value from pg_constraint x join pg_class c on c.oid=x.conrelid join ns n on n.oid=c.relnamespace where x.contype<>'n'),
indexes as(select schemaname||'.'||indexname key,jsonb_build_object('relation',schemaname||'.'||tablename,'hash',md5(indexdef)) value from pg_indexes where schemaname in(select nspname from ns)),
schemas as(select n.nspname key,jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'access',(select jsonb_object_agg(r.name,jsonb_build_array(has_schema_privilege(r.name,n.oid,'USAGE'),has_schema_privilege(r.name,n.oid,'CREATE'))) from roles r),'publicAccess',exists(select 1 from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x where x.grantee=0)) value from ns n)
select jsonb_build_object('relations',(select coalesce(jsonb_object_agg(key,value),'{}') from relations),'functions',(select coalesce(jsonb_object_agg(key,value),'{}') from functions),'policies',(select coalesce(jsonb_object_agg(key,value),'{}') from policies),'triggers',(select coalesce(jsonb_object_agg(key,value),'{}') from triggers),'constraints',(select coalesce(jsonb_object_agg(key,value),'{}') from constraints),'indexes',(select coalesce(jsonb_object_agg(key,value),'{}') from indexes),'schemas',(select coalesce(jsonb_object_agg(key,value),'{}') from schemas)) snapshot) catalog; expected:=d->'dependencies';mismatches:='[]'::jsonb;for g in select jsonb_object_keys(expected) loop for k,v in select * from jsonb_each(expected->g) loop
 a:=coalesce(observed->g->k,'null'::jsonb);if a is distinct from v then
  mismatches:=mismatches||jsonb_build_array(jsonb_build_object('group',g,'object',k,'fields',case when jsonb_typeof(v)='object' and jsonb_typeof(a)='object' then (select jsonb_agg(field order by field collate "C") from (select jsonb_object_keys(v) field union select jsonb_object_keys(a) field) f where v->field is distinct from a->field) else jsonb_build_array('presence') end));
 end if;end loop;end loop; if jsonb_array_length(mismatches)>0 then raise exception 'QGR_DEPENDENCY_MISMATCH' using detail=(select jsonb_agg(value)::text from(select value from jsonb_array_elements(mismatches) limit 30)x);end if;
 expected:=d->'pre';mismatches:='[]'::jsonb;for g in select jsonb_object_keys(expected) loop for k,v in select * from jsonb_each(expected->g) loop
 a:=coalesce(observed->g->k,'null'::jsonb);if a is distinct from v then
  mismatches:=mismatches||jsonb_build_array(jsonb_build_object('group',g,'object',k,'fields',case when jsonb_typeof(v)='object' and jsonb_typeof(a)='object' then (select jsonb_agg(field order by field collate "C") from (select jsonb_object_keys(v) field union select jsonb_object_keys(a) field) f where v->field is distinct from a->field) else jsonb_build_array('presence') end));
 end if;end loop;end loop; if to_regnamespace('mail_quota') is not null then mismatches:=mismatches||jsonb_build_array(jsonb_build_object('group','schemas','object','mail_quota','fields',jsonb_build_array('already_present')));end if;select jsonb_build_object('queued',(select count(*) from public.outbox where status='queued'),'sending',(select count(*) from public.outbox where status='sending'),'uncertain',(select count(*) from public.outbox where status='uncertain'),
 'jobs',(select count(*) from public.jobs where status='running'),'campaigns',(select count(*) from public.campaigns where status='active'),'enrollments',(select count(*) from public.campaign_enrollments where status='active'),
 'attempts',(select count(*) from mail_runtime.attempts where state in('reserved','admitted','uncertain')),'cycles',(select count(*) from mail_runtime.sync_cycles where state in('active','uncertain')),
 'draining',(select count(*) from mail_runtime.routes where state='draining'),'brandAdmissions',(select count(*) from public.mail_brand_dispatch_admissions where outcome in('admitted','uncertain'))) into queue_state;
 queue_ok:=not exists(select 1 from jsonb_each_text(queue_state) x where x.value::bigint<>0);
 perform set_config('pipeline_os.qgr_final_report',jsonb_build_object('protocol','QGR-FINAL-r1','ordinal','052','contractSha256','28e2e365438d1725f271e8d724d87f8f90516803d65f62d844cc5ebeac8a0921','catalogOk',jsonb_array_length(mismatches)=0,'queueOk',queue_ok,'queue',queue_state,'mismatchCount',jsonb_array_length(mismatches),'mismatches',(select coalesce(jsonb_agg(value),'[]') from(select value from jsonb_array_elements(mismatches) limit 30)x),'publicationReady',false,'limits',jsonb_build_array('snapshot_not_process_pause','remote_identity_and_flags_not_checked','linux_build_and_operator_release_authorization_required'))::text,true);end $qgr$;
